import {checkinHTML} from './checkin.mjs';
import {fingerprint,analyzeText,recordsForPerson,applyReview,nameKey,needsReading,syncDetectedParticipants,extractPurchase,journeysForPerson,syncJourneys} from './document-model.mjs';
import {extractDocument,supportedFile,releaseOCR,documentFormat} from './document-reader.mjs';
export function createDocumentFeatures(ctx){const {esc,field,select,modal,toast,read,persist,render,getTrip,getState,localFile}=ctx;let job=null;let reviewRows=[],reviewPath='',reviewTripId='';const el=s=>document.querySelector(s);const reading=(t,path)=>t.readings?.[path];const pending=t=>t.files.filter(f=>{const r=reading(t,f.path);return r&&r.reviewedFingerprint!==r.fingerprint&&r.status!=='ignored'}).length;
function panel(t){return `<section class="reader-panel"><div><h3>Llegir i associar documents</h3><p>Detecta passatgers i trajectes en PDF, Excel, CSV i imatges. Els documents s’associen als participants de l’Excel. Els noms que no hi coincideixen queden per revisar i no creen persones noves.</p><span class="small muted">${pending(t)} documents per revisar · Lectura al teu ordinador</span></div><div class="actions"><button class="button" data-action="analyze-documents" ${job?'disabled':''}>Llegir documents</button>${pending(t)?'<button class="button secondary" data-action="review-next">Revisar propostes</button>':''}</div><div id="readingProgress" class="reading-progress" role="status" aria-live="polite">${job?.tripId===t.id?progressHTML():''}</div></section>`}
function progressHTML(){return `<span>${esc(job.message||'Preparant lectura…')}</span><progress value="${job.done}" max="${job.total||1}"></progress><button class="text-button" data-action="stop-reading">Aturar lectura</button>`}
function updateProgress(message){if(!job)return;job.message=message;const node=el('#readingProgress');if(node&&getTrip()?.id===job.tripId)node.innerHTML=progressHTML()}
function status(t,f){const r=reading(t,f.path);if(!r||r.status==='unread')return '<span class="status neutral">Sense llegir</span>';if(r.fingerprint!==fingerprint(f))return '<span class="status">Document modificat</span>';if(r.status==='error')return '<span class="status">Lectura no completada</span>';if(r.status==='unsupported')return '<span class="status neutral">Associació manual</span>';if(r.status==='ignored')return '<span class="status neutral">Omesa</span>';if(r.reviewedFingerprint===r.fingerprint){const names=(r.confirmed||[]).map(c=>t.people.find(p=>p.id===c.personId)?.name).filter(Boolean);return `<span class="status done">Associat</span><small>${names.map(esc).join(', ')}</small>`}return `<span class="status">${r.proposals?.length||0} coincidències · Revisar</span>`}
async function analyze(t=getTrip(),path){if(t?.rosterMode==='excel'&&!t.people.length){toast('Importa primer l’Excel de participants.');return}if(job){toast('Ja hi ha una lectura en curs.');return}if(!t?.files.length){toast('Vincula una carpeta amb documents.');return}const requested=t.files.filter(f=>path?f.path===path:needsReading(f,t.readings?.[f.path]));const files=requested.slice(0,100);const cached=syncDetectedParticipants(t);if(cached.added||cached.linked||cached.updated)await persist();if(!files.length){toast(cached.added?`${cached.added} participants creats a partir dels documents llegits.`:t.people.length?'Llistat de participants actualitzat. Revisa els trajectes detectats.':'No s’han detectat noms de passatger. Obre «Revisar / associar» per veure el text llegit.');ctx.goToParticipants();return}job={tripId:t.id,added:cached.added,done:0,total:files.length,message:'Preparant lectura…',controller:new AbortController()};ctx.goToDocuments();try{const saved=await read('folders',t.id);if(!saved)throw Error('Torna a vincular la carpeta per poder llegir-la.');if(saved.handle&&await saved.handle.requestPermission({mode:'read'})!=='granted')throw Error('Cal donar permís de lectura a la carpeta.');t.readings??={};for(const meta of files){if(job.controller.signal.aborted)break;const old=t.readings[meta.path];updateProgress(`${job.done+1}/${files.length} · ${meta.name}`);let result;try{let file;if(saved.handle){let dir=saved.handle;const parts=meta.path.split('/');for(const part of parts.slice(0,-1))dir=await dir.getDirectoryHandle(part);file=await(await dir.getFileHandle(parts.at(-1))).getFile()}else{file=saved.files?.find(f=>f.path===meta.path)?.file;if(!file)throw Error('Document no disponible. Actualitza la carpeta.');}if(!supportedFile(meta.name)&&await documentFormat(file)!=='pdf'){result={status:'unsupported',text:'',proposals:[],warnings:['Format no compatible. Pots associar aquest document manualment.']}}else{const content=await extractDocument(file,{signal:job.controller.signal,progress:message=>updateProgress(`${job.done+1}/${files.length} · ${meta.name} · ${message}`)});const parsed=t.rosterMode==='excel'&&meta.name===t.rosterSource?{text:content.text,proposals:[],warnings:['Llista oficial de participants. Les reserves s’associen des dels altres documents.']}:analyzeText({...content,people:t.people,name:meta.name});result={...parsed,warnings:[...content.warnings,...parsed.warnings],method:content.method,status:'ready'}}}catch(e){if(e.name==='AbortError')break;result={status:'error',text:'',proposals:[],warnings:[e.message||'No s’ha pogut llegir aquest document.']}}t.readings[meta.path]={...result,name:meta.name,fingerprint:fingerprint(meta),readAt:Date.now(),confirmed:old?.confirmed||[],reviewedAt:old?.reviewedAt||null,reviewedFingerprint:old?.reviewedFingerprint||null,dismissedNames:old?.dismissedNames||[]};const synced=syncDetectedParticipants(t);job.added+=synced.added;job.done++;await persist();}toast(job.controller.signal.aborted?'Lectura aturada. Les propostes ja llegides s’han guardat.':`${job.done} documents llegits · ${job.added} participants nous · ${t.people.length} participants al viatge. Revisa els trajectes.${requested.length>100?' Prem «Llegir documents» per continuar amb la resta.':''}`)}finally{await releaseOCR().catch(()=>{});job=null;if(getTrip()?.id===t.id&&t.people.length)ctx.goToParticipants();else render()}}
function rowHTML(row,i,t){return `<section class="association-row" data-row="${i}"><div class="association-head"><label class="check-label"><input type="checkbox" name="enabled_${i}" ${row.enabled?'checked':''}> Associar aquesta persona</label><button type="button" class="text-button error" data-action="remove-association" data-id="${i}">Treure</button></div><div class="form-grid">${select('Participant','person_'+i,row.personId||'',[['',t.rosterMode==='excel'?'Selecciona un participant de l’Excel':'Crear participant / nom detectat'],...t.people.map(p=>[p.id,p.name])])}${field('Nom detectat o participant nou','newname_'+i,row.name||'')}</div><fieldset class="purchase-fields"><legend>Dades de compra</legend><div class="form-grid">${field('Referència de compra',`purchaseReference_${i}`,row.purchase?.reference||'')}${field('Email de compra',`purchaseEmail_${i}`,row.purchase?.email||'','email')}</div></fieldset>${row.unmatched?'<div class="notice">Aquest nom no coincideix amb la llista de l’Excel. Selecciona la persona correcta o deixa’l sense associar.</div>':''}${row.nameVariant?'<div class="notice">El nom d’aquest document té una variant o menys cognoms. Comprova l’associació proposada.</div>':''}${row.evidence?`<p class="evidence"><strong>Text del document:</strong> ${esc(row.evidence)}</p>`:''}<div class="journey-editor">${row.segments.map((s,j)=>`<fieldset><legend>Trajecte ${j+1}</legend><div class="form-grid">${field('Origen',`origin_${i}_${j}`,s.origin)}${field('Destinació',`destination_${i}_${j}`,s.destination)}${field('Sortida · data i hora',`departure_${i}_${j}`,s.departure)}${field('Arribada · data i hora',`arrival_${i}_${j}`,s.arrival)}${field('Vol / tren / vehicle',`service_${i}_${j}`,s.service)}${field('Localitzador',`reference_${i}_${j}`,s.reference)}</div><button type="button" class="text-button error" data-action="remove-segment" data-id="${i}:${j}">Treure trajecte</button></fieldset>`).join('')}</div><button type="button" class="text-button" data-action="add-segment" data-id="${i}">＋ Afegir trajecte</button></section>`}
function collect(){const form=el('#modalForm'),data=new FormData(form);reviewRows=reviewRows.map((r,i)=>({...r,enabled:data.has('enabled_'+i),personId:data.get('person_'+i)||'',name:String(data.get('newname_'+i)||'').trim(),purchase:{reference:String(data.get('purchaseReference_'+i)||'').trim(),email:String(data.get('purchaseEmail_'+i)||'').trim()},segments:r.segments.map((s,j)=>Object.fromEntries(['origin','destination','departure','arrival','service','reference'].map(key=>[key,String(data.get(`${key}_${i}_${j}`)||'').trim()])))}))}
function drawRows(){const t=getState().trips.find(t=>t.id===reviewTripId);el('#associationRows').innerHTML=reviewRows.map((r,i)=>rowHTML(r,i,t)).join('')}
function review(path){const t=getTrip(),f=t.files.find(f=>f.path===path);if(!t||!f)return;let r=reading(t,path);if(!r){t.readings??={};r=t.readings[path]={name:f.name,fingerprint:fingerprint(f),text:'',status:'unread',proposals:[],warnings:['Aquest document encara no s’ha llegit. Pots associar-lo manualment o prémer «Llegir documents».']}}reviewPath=path;reviewTripId=t.id;if(r.reviewedFingerprint===r.fingerprint&&r.confirmed?.length){reviewRows=r.confirmed.map(c=>({enabled:true,personId:c.personId,name:t.people.find(p=>p.id===c.personId)?.name||'',purchase:structuredClone(c.purchase||r.purchase||{}),segments:structuredClone(c.segments||[])}))}else reviewRows=(r.proposals||[]).map(p=>({...structuredClone(p),enabled:!p.ambiguous&&!!p.personId}));if(!reviewRows.length)reviewRows=[{enabled:true,name:'',personId:'',purchase:r.purchase||extractPurchase(r.text||''),segments:[]}];modal('Revisar document i passatgers',`<p class="document-title">${esc(f.name)}</p><p class="muted small">Comprova els noms i els trajectes. Les associacions es guardaran a les fitxes sense canviar els estats de bitllet o check-in.</p>${(r.warnings||[]).map(w=>`<div class="notice">${esc(w)}</div>`).join('')}<details class="source-text"><summary>Veure el text llegit ${r.method?'· '+esc(r.method):''}</summary><pre>${esc(r.text||'No hi ha text disponible.')}</pre></details><div id="associationRows"></div><button type="button" class="button secondary" data-action="add-association">＋ Una altra persona</button><div class="row-links"><button type="button" class="text-button" data-action="reread-document" data-id="${esc(path)}">Tornar a llegir el document</button><button type="button" class="text-button" data-action="ignore-document" data-id="${esc(path)}">Ometre aquest document</button></div>`,async()=>{collect();const current=getState().trips.find(x=>x.id===reviewTripId);const draft=applyReview(current,reviewPath,reviewRows);await ctx.saveTrip(draft);toast('Document i trajectes associats als participants.')},'Confirmar associacions');el('#modal').classList.add('document-modal');drawRows()}
function next(){const t=getTrip(),f=t.files.find(f=>{const r=reading(t,f.path);return r&&r.reviewedFingerprint!==r.fingerprint&&r.status!=='ignored'});if(f)review(f.path);else toast('No queden propostes per revisar.')}
function journeySummary(t,p){const journeys=journeysForPerson(t,p.id);return journeys.length?`<div class="participant-journeys">${journeys.map(s=>`<div class="person-journey"><strong>${esc(s.origin||'Origen pendent')} → ${esc(s.destination||'Destinació pendent')}</strong><small>${esc(s.service||'Servei pendent')}${s.departure?' · '+esc(s.departure):''}</small>${s.arrival?`<small>Arribada: ${esc(s.arrival)}</small>`:''}${s.pending?'<small>Associat automàticament · per revisar</small>':''}${s.stale?'<small>Document modificat · revisa l’associació</small>':''}</div>`).join('')}</div>`:''}
function arrivalSummary(t,p){if(p.arrival)return esc(p.arrival);const journeys=journeysForPerson(t,p.id);return journeys.length?journeys.map(s=>`<small>${esc(s.destination||'Destinació pendent')} · ${esc(s.arrival||'Hora pendent')}</small>`).join(''):'Per confirmar'}
function originSummary(t,p){return esc(p.origin||journeysForPerson(t,p.id)[0]?.origin||'Origen pendent')}
function personSummary(t,p){const records=recordsForPerson(t,p.id);return records.length?`<button type="button" class="text-button" data-action="person-documents" data-id="${p.id}">${records.length} document${records.length===1?'':'s'} · Veure trajectes →</button>`:''}
function personDocuments(id){const t=getTrip(),p=t.people.find(p=>p.id===id);if(!p)return;const records=recordsForPerson(t,id);modal(`Documents de ${p.name}`,records.length?records.map(r=>`<section class="panel"><h3>${esc(r.name)}</h3>${r.pending?'<p class="status">Detectat automàticament · pendent de revisió</p>':''}${r.stale?'<p class="status">El document ha canviat. Associació anterior pendent de revisió.</p>':''}${r.missing?'<p class="status">Document fora de la carpeta actual</p>':''}${(r.purchases||[]).map(p=>`<dl class="detail-list purchase-details"><div><dt>Referència de compra</dt><dd>${esc(p.reference||'No detectada')}</dd></div><div><dt>Email de compra</dt><dd>${esc(p.email||'No detectat')}</dd></div></dl>`).join('')}${r.segments.length?r.segments.map(s=>`<div class="person-journey"><strong>${esc(s.origin||'Origen per confirmar')} → ${esc(s.destination||'Destinació per confirmar')}</strong><dl class="detail-list"><div><dt>Sortida</dt><dd>${esc(s.departure||'Per confirmar')}</dd></div><div><dt>Arribada</dt><dd>${esc(s.arrival||'Per confirmar')}</dd></div><div><dt>Servei</dt><dd>${esc(s.service||'Sense indicar')}</dd></div><div><dt>Localitzador</dt><dd>${esc(s.reference||'Sense indicar')}</dd></div></dl></div>`).join(''):'<p class="muted">Document associat sense trajectes detallats.</p>'}${!r.missing?`<div class="actions"><button type="button" class="button secondary" data-action="download-file" data-id="${t.files.findIndex(f=>f.path===r.path)}">Descarregar document</button><button type="button" class="button secondary" data-action="review-document" data-id="${esc(r.path)}">Revisar associació</button></div>`:''}</section>`).join(''):'<p>No té documents associats.</p>',async()=>{},'Tancar');el('#modal').classList.add('document-modal')}
function personCheckin(id){const t=getTrip(),p=t.people.find(p=>p.id===id);if(!p)return;modal(`Check-in · ${p.name}`,checkinHTML(t,p,esc)+select('Estat del check-in de tots els vols','checkin',p.checkin||'Pendent',['Pendent','Fet','No cal']),async data=>{const draft=structuredClone(t);draft.people.find(x=>x.id===id).checkin=data.checkin;await ctx.saveTrip(draft);toast('Estat del check-in guardat.')},'Guardar estat');el('#modal').classList.add('document-modal')}
function personStatus(t,p){const records=recordsForPerson(t,p.id);return records.some(r=>r.pending)?'<span class="status">Trajectes associats · per revisar</span>':''}
function purchaseSummary(p){return (p.purchases||[]).map(b=>`<small class="purchase-summary">${b.reference?'Ref. '+esc(b.reference):'Referència pendent'}${b.email?'<br>'+esc(b.email):''}</small>`).join('')}
return {panel,status,journeySummary,arrivalSummary,originSummary,personSummary,personStatus,purchaseSummary,analyze,isBusy:()=>!!job,pending,handlers:{'person-checkin':personCheckin,'analyze-documents':()=>analyze(),'review-next':next,'stop-reading':()=>{job?.controller.abort();updateProgress('Aturant després de la pàgina actual…')},'review-document':review,'person-documents':personDocuments,'reread-document':async path=>{el('#modal').close();await analyze(getTrip(),path);review(path)},'add-association':()=>{collect();reviewRows.push({enabled:true,name:'',personId:'',segments:[]});drawRows()},'remove-association':i=>{collect();reviewRows.splice(Number(i),1);drawRows()},'add-segment':i=>{collect();reviewRows[Number(i)].segments.push({});drawRows()},'remove-segment':key=>{collect();const[i,j]=key.split(':').map(Number);reviewRows[i].segments.splice(j,1);drawRows()},'ignore-document':async path=>{const t=getTrip(),r=reading(t,path);if(r?.confirmed?.length&&!confirm('Aquest document ja té associacions. Vols treure-les i ometre’l?'))return;if(r){const draft=structuredClone(t);draft.readings[path].status='ignored';draft.readings[path].confirmed=[];draft.readings[path].reviewedFingerprint=null;for(const p of draft.people)p.purchases=(p.purchases||[]).filter(b=>b.documentPath!==path);syncJourneys(draft);await ctx.saveTrip(draft)}el('#modal').close()}}}
}
